DO $content_index_tests$
DECLARE w text:='qa_content_index_'||replace(gen_random_uuid()::text,'-','');v_gen text;v_rev bigint;v_textrev text;v_header jsonb;v_value text;v_before jsonb;v_state bigint;v_count bigint;
BEGIN
 PERFORM fountain_cloud.store_lock(w);PERFORM set_config('fountain.workspace_id',w,true);
 INSERT INTO fountain_private.entities VALUES(w,'page','legacy','{"id":"legacy","title":"Legacy","owner_id":"forged-body-owner","blocks":[{"text":"historical"}]}'::jsonb,'2026-10-01','2026-10-01');
 IF (SELECT creator_id FROM fountain_private.content_provenance WHERE workspace_id=w AND kind='page' AND id='legacy') IS NOT NULL THEN RAISE EXCEPTION 'Unverified source owner became creator';END IF;
 SELECT generation,text_revision INTO v_gen,v_textrev FROM fountain_private.content_search_documents WHERE workspace_id=w AND kind='page' AND id='legacy';
 PERFORM set_config('fountain.content_actor',jsonb_build_object('workspace_id',w,'member_id','actor','cause','human')::text,true);
 INSERT INTO fountain_private.entities VALUES(w,'page','new',jsonb_build_object('id','new','title','Ｆａｍｉｌｙ Straße','owner_id','forged','actor','forged','verification',jsonb_build_object('secret','NEVER-PROOF'),'blocks',jsonb_build_array(jsonb_build_object('type','paragraph','text',repeat('a',4090)||' BOUNDARY PHRASE '||repeat('b',10000)||' FAR-END-NEEDLE'),jsonb_build_object('type','attachment','text','NEVER-ATTACHMENT'),jsonb_build_object('type','paragraph','text','NEVER-ATTACHMENT-ID','attachment_id','x'),jsonb_build_object('type','mystery','text','NEVER-EXTENSION'),jsonb_build_object('type',NULL,'text','NEVER-NULL-TYPE'))),'2026-10-17T01:00:00+00:00','2026-10-17T01:00:00+00:00');
 IF NOT EXISTS(SELECT 1 FROM fountain_private.content_provenance WHERE workspace_id=w AND id='new' AND creator_id='actor' AND editor_id='actor' AND creator_cause='human') THEN RAISE EXCEPTION 'Trusted actor creator missing';END IF;
 IF NOT EXISTS(SELECT 1 FROM fountain_private.content_search_chunks WHERE workspace_id=w AND id='new' AND position('boundary phrase' IN folded_value)>0)
  OR NOT EXISTS(SELECT 1 FROM fountain_private.content_search_chunks WHERE workspace_id=w AND id='new' AND position('far-end-needle' IN folded_value)>0)
  OR EXISTS(SELECT 1 FROM fountain_private.content_search_chunks WHERE workspace_id=w AND folded_value LIKE '%never-%') THEN RAISE EXCEPTION 'Chunk/extraction coverage failed';END IF;
 IF EXISTS(SELECT 1 FROM fountain_private.content_search_chunks WHERE workspace_id=w AND id='new' AND length(text_value)>4096) THEN RAISE EXCEPTION 'Chunk bound exceeded';END IF;
 PERFORM set_config('fountain.content_actor',jsonb_build_object('workspace_id',w,'member_id','manager','cause','human')::text,true);
 UPDATE fountain_private.entities SET data=data||'{"permissions":{"default":"private"}}'::jsonb,updated_at='2026-10-17T02:00:00+00:00' WHERE workspace_id=w AND kind='page' AND id='new';
 IF NOT EXISTS(SELECT 1 FROM fountain_private.content_provenance WHERE workspace_id=w AND id='new' AND editor_id='actor' AND edited_at='2026-10-17T01:00:00+00:00' AND manager_id='manager') THEN RAISE EXCEPTION 'Header-only change mislabeled editor';END IF;
 PERFORM set_config('fountain.content_actor','',true);
 UPDATE fountain_private.entities SET data=data||'{"blocks":[{"text":"direct SQL unknown editor"}]}'::jsonb WHERE workspace_id=w AND kind='page' AND id='legacy';
 IF NOT EXISTS(SELECT 1 FROM fountain_private.content_provenance WHERE workspace_id=w AND id='legacy' AND creator_id IS NULL AND editor_id IS NULL AND editor_cause='unknown') THEN RAISE EXCEPTION 'Direct SQL invented provenance';END IF;
 DELETE FROM fountain_private.entities WHERE workspace_id=w AND kind='page' AND id='legacy';
 INSERT INTO fountain_private.entities VALUES(w,'page','legacy','{"id":"legacy","title":"Legacy","blocks":[]}'::jsonb,'2026-10-01','2026-10-01');
 IF (SELECT generation FROM fountain_private.content_search_documents WHERE workspace_id=w AND id='legacy')=v_gen THEN RAISE EXCEPTION 'Resource generation reused';END IF;

 PERFORM set_config('fountain.content_actor',jsonb_build_object('workspace_id',w,'member_id','author','cause','automation')::text,true);
 INSERT INTO fountain_private.entities VALUES(w,'database','db','{"id":"db","name":"Typed","description":"description text","properties":[{"id":"t","type":"title"},{"id":"s","type":"text"},{"id":"n","type":"number"},{"id":"c","type":"checkbox"},{"id":"m","type":"multi_select"},{"id":"d","type":"date"},{"id":"owner","type":"owner"},{"id":"ver","type":"verification"}],"row_permissions":{"mode":"assigned","property_id":"m"}}'::jsonb,'2026-10-17','2026-10-17');
 INSERT INTO fountain_private.entities VALUES(w,'row','row','{"id":"row","database_id":"db","properties":{"t":"Row title","s":"Authored body","n":1.0,"c":true,"m":["member-id","EMAIL@example.test"],"d":{"start":"2026-01-01","end":"2026-01-02"},"owner":["NEVER-OWNER"],"ver":{"status":"NEVER-VERIFICATION"},"extension":"NEVER-EXTENSION"},"verification":{"proof":"NEVER-PROOF"}}'::jsonb,'2026-10-17','2026-10-17');
 IF (SELECT string_agg(text_value,' ' ORDER BY ordinal) FROM fountain_private.content_search_chunks WHERE workspace_id=w AND id='row')<>'Row title Authored body 1 true member-id EMAIL@example.test 2026-01-01 2026-01-02' THEN RAISE EXCEPTION 'Typed authored extraction differs';END IF;
 SELECT header INTO v_header FROM fountain_private.content_search_documents WHERE workspace_id=w AND id='row';
 IF v_header->'assignment_values'<>'["member-id","EMAIL@example.test"]'::jsonb OR v_header ? 'properties' OR v_header ? 'verification' THEN RAISE EXCEPTION 'Row header contains raw/proof fields';END IF;
 SELECT header INTO v_header FROM fountain_private.content_search_documents WHERE workspace_id=w AND id='db';
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_header->'properties') p WHERE p-ARRAY['id','type']<>'{}'::jsonb) THEN RAISE EXCEPTION 'Database schema header leaked options';END IF;
 UPDATE fountain_private.entities SET data=data||'{"properties":[{"id":"s","type":"title"},{"id":"m","type":"multi_select"}],"row_permissions":{"mode":"assigned","property_id":"s"}}'::jsonb WHERE workspace_id=w AND kind='database' AND id='db';
 IF NOT EXISTS(SELECT 1 FROM fountain_private.content_search_documents WHERE workspace_id=w AND id='row' AND title='Authored body' AND header->'assignment_values'='["Authored body"]'::jsonb) THEN RAISE EXCEPTION 'Database child refresh stale';END IF;
 IF NOT EXISTS(SELECT 1 FROM fountain_private.content_provenance WHERE workspace_id=w AND id='row' AND editor_id='author' AND editor_cause='automation') THEN RAISE EXCEPTION 'Schema projection changed content editor';END IF;
 UPDATE fountain_private.entities SET data=data||'{"properties":null}'::jsonb WHERE workspace_id=w AND kind='database' AND id='db';
 IF EXISTS(SELECT 1 FROM fountain_private.content_search_documents WHERE workspace_id=w AND id IN('db','row') AND validity) THEN RAISE EXCEPTION 'Malformed schema allowed default';END IF;

 -- Formatting, NFKC-equivalent text, icon and moves are real authored
 -- changes even if the searchable text hash remains identical.
 PERFORM set_config('fountain.content_actor',jsonb_build_object('workspace_id',w,'member_id','original-editor','cause','human')::text,true);
 INSERT INTO fountain_private.entities VALUES(w,'page','semantic','{"id":"semantic","title":"Semantic","blocks":[{"text":"é","bold":false}]}'::jsonb,'2026-10-17','2026-10-17');
 SELECT text_revision INTO v_textrev FROM fountain_private.content_search_documents WHERE workspace_id=w AND id='semantic';
 PERFORM set_config('fountain.content_actor',jsonb_build_object('workspace_id',w,'member_id','format-editor','cause','human')::text,true);
 UPDATE fountain_private.entities SET data=data||'{"blocks":[{"text":"é","bold":true}]}'::jsonb,updated_at='2026-10-17T03:00:00+00:00' WHERE workspace_id=w AND id='semantic';
 IF NOT EXISTS(SELECT 1 FROM fountain_private.content_provenance WHERE workspace_id=w AND id='semantic' AND editor_id='format-editor' AND edited_at='2026-10-17T03:00:00+00:00' AND manager_id IS NULL) OR(SELECT text_revision FROM fountain_private.content_search_documents WHERE workspace_id=w AND id='semantic')<>v_textrev THEN RAISE EXCEPTION 'Normalized-equivalent formatting editor lost';END IF;
 PERFORM set_config('fountain.content_actor',jsonb_build_object('workspace_id',w,'member_id','icon-editor','cause','human')::text,true);
 UPDATE fountain_private.entities SET data=data||'{"icon":"📚","parent_id":"new-parent"}'::jsonb WHERE workspace_id=w AND id='semantic';
 IF NOT EXISTS(SELECT 1 FROM fountain_private.content_provenance WHERE workspace_id=w AND id='semantic' AND editor_id='icon-editor' AND manager_id IS NULL) THEN RAISE EXCEPTION 'Icon/move authored editor lost';END IF;

 SELECT content_revision INTO v_state FROM fountain_private.content_search_state WHERE workspace_id=w;
 INSERT INTO fountain_private.entities VALUES(w,'audit','audit','{"id":"audit"}'::jsonb,'now','now');
 IF (SELECT content_revision FROM fountain_private.content_search_state WHERE workspace_id=w)<>v_state THEN RAISE EXCEPTION 'Audit invalidated content cursor';END IF;
 INSERT INTO fountain_private.entities VALUES(w,'group','group','{"id":"group","members":["actor"]}'::jsonb,'now','now');
 IF (SELECT content_revision FROM fountain_private.content_search_state WHERE workspace_id=w)<=v_state THEN RAISE EXCEPTION 'ACL group did not invalidate cursor';END IF;
 IF EXISTS(SELECT 1 FROM fountain_private.meta WHERE workspace_id=w AND key IN('_entity_revision','access_revision')) THEN RAISE EXCEPTION 'Derivative trigger changed source counters';END IF;
 SELECT content_revision INTO v_state FROM fountain_private.content_search_state WHERE workspace_id=w;
 BEGIN
  UPDATE fountain_private.entities SET data=data||'{"title":"rollback"}'::jsonb WHERE workspace_id=w AND kind='page' AND id='new';
  RAISE EXCEPTION USING ERRCODE='Z0002',MESSAGE='rollback';
 EXCEPTION WHEN SQLSTATE 'Z0002' THEN NULL;END;
 IF (SELECT content_revision FROM fountain_private.content_search_state WHERE workspace_id=w)<>v_state OR (SELECT title FROM fountain_private.content_search_documents WHERE workspace_id=w AND id='new')='rollback' THEN RAISE EXCEPTION 'Index transaction leaked rollback';END IF;
 SELECT count(*) INTO v_count FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='fountain_private' AND c.relname IN('content_search_documents','content_search_chunks','content_provenance','content_search_state') AND c.relrowsecurity AND c.relforcerowsecurity AND NOT has_table_privilege('anon',c.oid,'SELECT') AND NOT has_table_privilege('authenticated',c.oid,'SELECT') AND NOT has_table_privilege('service_role',c.oid,'SELECT');
 IF v_count<>4 THEN RAISE EXCEPTION 'Index tables RLS/grants unsafe';END IF;
END $content_index_tests$;


DO $origin_tests$
DECLARE w text:='qa_content_origin_'||replace(gen_random_uuid()::text,'-','');v_data jsonb;v_changes jsonb;v_parent text;v_bad jsonb;v_result bigint;v_rev bigint;
BEGIN
 PERFORM fountain_cloud.store_lock(w);PERFORM set_config('fountain.workspace_id',w,true);
 INSERT INTO fountain_private.entities SELECT w,'member',x.id,jsonb_build_object('id',x.id,'name',x.id,'role',x.role,'active',true),'2026-10-17','2026-10-17' FROM(VALUES('actor','member'),('author','member'),('guest','guest')) x(id,role);
 v_parent:=jsonb_build_object('workspace_id',w,'member_id','actor','cause','human')::text;
 PERFORM set_config('fountain.content_actor',v_parent,true);
 v_data:='{"id":"one","title":"One","blocks":[{"text":"One text"}],"created_at":"2026-10-17","updated_at":"2026-10-17"}'::jsonb;
 v_changes:=jsonb_build_array(jsonb_build_object('op','put','kind','page','id','one','data',v_data,'previousCreatedAt',NULL,'origin',jsonb_build_object('member_id','author','cause','automation')),
 jsonb_build_object('op','put','kind','page','id','two','data',v_data||'{"id":"two"}'::jsonb,'previousCreatedAt',NULL,'origin',jsonb_build_object('member_id','actor','cause','import')));
 v_result:=fountain_cloud.store_apply_changes_locked(w,0,v_changes);
 IF v_result<>2 OR NOT EXISTS(SELECT 1 FROM fountain_private.content_provenance WHERE workspace_id=w AND id='one' AND creator_id='author' AND creator_cause='automation') OR NOT EXISTS(SELECT 1 FROM fountain_private.content_provenance WHERE workspace_id=w AND id='two' AND creator_id='actor' AND creator_cause='import') OR current_setting('fountain.content_actor')<>v_parent THEN RAISE EXCEPTION 'Per-put trusted origin or ACK restoration failed';END IF;
 v_changes:=jsonb_build_array(jsonb_build_object('op','put','kind','page','id','legacy','data',v_data||'{"id":"legacy","actor":"forged","origin":{"member_id":"forged","cause":"automation"}}'::jsonb,'previousCreatedAt',NULL));
 v_result:=fountain_cloud.store_apply_changes_locked(w,2,v_changes);
 IF v_result<>3 OR NOT EXISTS(SELECT 1 FROM fountain_private.content_provenance WHERE workspace_id=w AND id='legacy' AND creator_id='actor' AND creator_cause='human') THEN RAISE EXCEPTION 'Source data origin gained trust';END IF;
 FOR v_bad IN SELECT value FROM jsonb_array_elements('[{"member_id":"author","cause":"human"},{"member_id":"actor","cause":"human","extra":true},{"member_id":"guest","cause":"automation"},{"member_id":"missing","cause":"automation"},null,{}]'::jsonb) LOOP
  BEGIN
   v_result:=fountain_cloud.store_apply_changes_locked(w,3,jsonb_build_array(jsonb_build_object('op','put','kind','page','id','invalid','data',v_data||'{"id":"invalid"}'::jsonb,'previousCreatedAt',NULL,'origin',v_bad)));
   RAISE EXCEPTION 'Invalid outer origin accepted';
  EXCEPTION WHEN SQLSTATE '22023' THEN NULL;END;
 END LOOP;
 PERFORM set_config('fountain.content_actor','',true);
 BEGIN v_result:=fountain_cloud.store_apply_changes_locked(w,3,jsonb_build_array(jsonb_build_object('op','put','kind','page','id','invalid','data',v_data||'{"id":"invalid"}'::jsonb,'previousCreatedAt',NULL,'origin',jsonb_build_object('member_id','actor','cause','human'))));RAISE EXCEPTION 'Origin without verified parent accepted';EXCEPTION WHEN SQLSTATE '22023' THEN NULL;END;
 PERFORM set_config('fountain.content_actor',v_parent,true);
 BEGIN v_result:=fountain_cloud.store_apply_changes_locked(w,3,jsonb_build_array(jsonb_build_object('op','delete','kind','page','id','one','origin',jsonb_build_object('member_id','actor','cause','human'))));RAISE EXCEPTION 'Delete origin accepted';EXCEPTION WHEN SQLSTATE '22023' THEN NULL;END;
 BEGIN v_result:=fountain_cloud.store_apply_changes_locked(w,3,jsonb_build_array(jsonb_build_object('op','meta','key','test','value',true,'origin',jsonb_build_object('member_id','actor','cause','human'))));RAISE EXCEPTION 'Meta origin accepted';EXCEPTION WHEN SQLSTATE '22023' THEN NULL;END;
 SELECT content_revision INTO v_rev FROM fountain_private.content_search_state WHERE workspace_id=w;
 UPDATE fountain_private.content_search_state SET content_revision=9007199254740991 WHERE workspace_id=w;
 BEGIN
  v_result:=fountain_cloud.store_apply_changes_locked(w,3,jsonb_build_array(jsonb_build_object('op','put','kind','page','id','invalid','data',v_data||'{"id":"invalid"}'::jsonb,'previousCreatedAt',NULL,'origin',jsonb_build_object('member_id','author','cause','automation'))));
  RAISE EXCEPTION 'Failed trigger accepted';
 EXCEPTION WHEN SQLSTATE 'PT413' THEN NULL;END;
 UPDATE fountain_private.content_search_state SET content_revision=v_rev WHERE workspace_id=w;
 IF current_setting('fountain.content_actor')<>v_parent OR EXISTS(SELECT 1 FROM fountain_private.entities WHERE workspace_id=w AND id='invalid') OR fountain_cloud.store_revision(w,'_entity_revision')<>3 THEN RAISE EXCEPTION 'Failed trigger leaked source/origin/counters';END IF;
 PERFORM set_config('fountain.content_actor',jsonb_build_object('workspace_id',w,'member_id','actor','cause','scim')::text,true);
 INSERT INTO fountain_private.entities VALUES(w,'page','scim-cause',v_data||'{"id":"scim-cause"}'::jsonb,'2026-10-17','2026-10-17');
 IF NOT EXISTS(SELECT 1 FROM fountain_private.content_provenance WHERE workspace_id=w AND id='scim-cause' AND creator_cause='system' AND editor_cause='system') THEN RAISE EXCEPTION 'SCIM cause escaped public enum';END IF;
END $origin_tests$;


DO $publication_tests$
DECLARE w text:='qa_content_publication_'||replace(gen_random_uuid()::text,'-','');v_id text;
BEGIN
 PERFORM fountain_cloud.store_lock(w);PERFORM set_config('fountain.workspace_id',w,true);
 PERFORM set_config('fountain.content_actor',jsonb_build_object('workspace_id',w,'member_id','content-author','cause','human')::text,true);
 FOREACH v_id IN ARRAY ARRAY['one','two'] LOOP
  INSERT INTO fountain_private.entities VALUES(w,'page',v_id,jsonb_build_object('id',v_id,'title',v_id,'blocks',jsonb_build_array(jsonb_build_object('text','authored'))),'2026-10-17','2026-10-17');
 END LOOP;
 INSERT INTO fountain_private.entities VALUES(w,'database','db','{"id":"db","name":"DB","properties":[]}'::jsonb,'2026-10-17','2026-10-17');
 PERFORM set_config('fountain.content_actor',jsonb_build_object('workspace_id',w,'member_id','publisher','cause','human')::text,true);
 INSERT INTO fountain_private.entities VALUES(w,'site','site','{"id":"site","page_id":"one","published":true}'::jsonb,'2026-10-17','2026-10-17');
 INSERT INTO fountain_private.entities VALUES(w,'form','form','{"id":"form","database_id":"db","published":true}'::jsonb,'2026-10-17','2026-10-17');
 IF(SELECT count(*) FROM fountain_private.content_provenance WHERE workspace_id=w AND id IN('one','db') AND manager_id='publisher' AND manager_at IS NOT NULL AND editor_id='content-author' AND creator_id='content-author')<>2 THEN RAISE EXCEPTION 'Publication changed editor or lost manager';END IF;
 PERFORM set_config('fountain.content_actor',jsonb_build_object('workspace_id',w,'member_id','mover','cause','human')::text,true);
 UPDATE fountain_private.entities SET data=data||'{"page_id":"two"}'::jsonb WHERE workspace_id=w AND kind='site' AND id='site';
 UPDATE fountain_private.entities SET data=data||'{"published":false}'::jsonb WHERE workspace_id=w AND kind='form' AND id='form';
 IF(SELECT count(*) FROM fountain_private.content_provenance WHERE workspace_id=w AND id IN('one','two','db') AND manager_id='mover' AND editor_id='content-author')<>3 THEN RAISE EXCEPTION 'Publication move/unpublish target provenance stale';END IF;
 PERFORM set_config('fountain.content_actor',jsonb_build_object('workspace_id',w,'member_id','remover','cause','human')::text,true);
 DELETE FROM fountain_private.entities WHERE workspace_id=w AND kind='site' AND id='site';
 IF NOT EXISTS(SELECT 1 FROM fountain_private.content_provenance WHERE workspace_id=w AND id='two' AND manager_id='remover' AND editor_id='content-author') THEN RAISE EXCEPTION 'Publication deletion lost manager';END IF;
 PERFORM set_config('fountain.content_actor','',true);
 INSERT INTO fountain_private.entities VALUES(w,'site','unknown','{"id":"unknown","page_id":"one","published":false}'::jsonb,'2026-10-17','2026-10-17');
 IF NOT EXISTS(SELECT 1 FROM fountain_private.content_provenance WHERE workspace_id=w AND id='one' AND manager_id IS NULL AND manager_at IS NULL AND editor_id='content-author') THEN RAISE EXCEPTION 'Unknown publication write retained false manager';END IF;
END $publication_tests$;
